<style>
.demand-grid{display:grid;grid-template-columns:minmax(0,1.25fr) minmax(320px,.75fr);gap:1rem}.demand-stack{display:grid;gap:1rem}.demand-card{border:1px solid var(--border);border-radius:18px;padding:1rem;background:var(--surface)}.demand-card h3{margin:.2rem 0 .45rem}.demand-card small{display:block;color:var(--muted);margin-top:.2rem}.demand-kpis{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:.7rem}.demand-kpis div{padding:.8rem;border-radius:14px;background:var(--surface-soft);border:1px solid var(--border)}.demand-kpis span{display:block;color:var(--muted);font-size:.78rem}.demand-kpis strong{font-size:1.15rem}.demand-actions{display:flex;gap:.6rem;flex-wrap:wrap;align-items:center}.demand-list{display:grid;gap:.55rem}.demand-list a{display:flex;justify-content:space-between;gap:1rem;padding:.8rem;border:1px solid var(--border);border-radius:14px;text-decoration:none;color:inherit}.demand-list a[aria-current="page"]{outline:2px solid var(--accent)}.demand-signal{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:.6rem}.demand-signal article{padding:.75rem;border:1px solid var(--border);border-radius:14px}.demand-signal b{display:block;font-size:1.05rem}.demand-history{display:grid;gap:.6rem}.demand-history article{padding:.75rem;border-left:3px solid var(--border);background:var(--surface-soft);border-radius:0 12px 12px 0}@media(max-width:980px){.demand-grid{grid-template-columns:1fr}.demand-kpis{grid-template-columns:1fr 1fr}}@media(max-width:620px){.demand-kpis,.demand-signal{grid-template-columns:1fr}}
</style>